SUSPICIOUS = ("system:", "ignore previous", "you are now the developer")


def flag(message):
    # Messages that imitate role headers such as "SYSTEM:" are held for a human.
    text = message.lower()
    return any(marker in text for marker in SUSPICIOUS)
